// Unit-base / carrier-pin colour relative to the player, driven by live diplomacy
// when it is enabled. Extra art (amber) is generated by tools/gen_unitbase_extra.py.
//
// Atlas names match what they look like: unitbase_green is green, unitbase_blue is blue.
// Paint (the original EasyTech convention, restored here):
//   本国            green
//   同盟 / 共同作战  blue
//   交战            red
//   敌对未开战      amber
//   中立            gray
// Colours are assigned to ALLIANCE connected components (transitive closure along
// ALLIANCE edges, same idea as warCascade in diplomacy.js), not by a single
// pairwise lookup against the player. Members of one camp therefore share a colour.
import { getDiplomaticRelation, DIPLOMACY_STATE } from './rules/diplomacy.js';
import { nativeAlliance } from './rules/combatModel.js';
import { COUNTRY_NAMES } from './api/names.js';

export const COLOR_FADE_SEC = 0.6;

export const BASE_COLOR_TABLE = {
  blue:  { hex: '#3a7eae', builtin: true },
  red:   { hex: '#a83a32', builtin: true },
  green: { hex: '#3d8f46', builtin: true },
  amber: { hex: '#d18a1f', source: 'gray' },
  gray:  { hex: '#7a7672', builtin: true },
};

export const KIND_COLOR = {
  player: 'green',
  alliance: 'blue',
  cobelligerent: 'blue',
  war: 'red',
  tense: 'amber',
  neutral: 'gray',
};

export const KIND_LABEL = {
  player: '本国',
  alliance: '同盟',
  cobelligerent: '共同作战',
  war: '交战',
  tense: '敌对未开战',
  neutral: '中立',
};

export const LEGEND_ITEMS = [
  { color: 'green', label: '本国' },
  { color: 'blue', label: '同盟 / 共同作战' },
  { color: 'red', label: '交战' },
  { color: 'amber', label: '敌对未开战' },
  { color: 'gray', label: '中立' },
];

export const EXTRA_BASE_COLORS = Object.keys(BASE_COLOR_TABLE).filter(k => BASE_COLOR_TABLE[k].source);

function living(c) { return c && !c.eliminated; }

// Transitive ALLIANCE closure starting at `start`. Read-only; does not touch diplomacy.js.
export function allianceComponent(game, start) {
  const st = game.stage;
  if (!st || !start) return new Set();
  const startC = st.countries.get(start);
  if (!startC) return new Set();
  if (startC.eliminated) return new Set([start]);

  const members = new Set([start]);
  const queue = [start];
  const all = [...st.countries.keys()];
  while (queue.length) {
    const cur = queue.shift();
    for (const other of all) {
      if (other === cur || members.has(other)) continue;
      if (!living(st.countries.get(other))) continue;
      if (getDiplomaticRelation(game, cur, other) === DIPLOMACY_STATE.ALLIANCE) {
        members.add(other);
        queue.push(other);
      }
    }
  }
  return members;
}

function campsShareWar(game, campA, campB) {
  const st = game.stage;
  for (const a of campA) {
    if (!living(st.countries.get(a))) continue;
    for (const b of campB) {
      if (a === b) continue;
      if (!living(st.countries.get(b))) continue;
      if (getDiplomaticRelation(game, a, b) === DIPLOMACY_STATE.WAR) return true;
    }
  }
  return false;
}

function campIsBelligerent(game, camp) {
  const st = game.stage;
  for (const a of camp) {
    for (const other of st.countries.values()) {
      if (!other || other.id === a) continue;
      if (getDiplomaticRelation(game, a, other.id) === DIPLOMACY_STATE.WAR) return true;
    }
  }
  return false;
}

function campHostileNative(game, camp, player) {
  const st = game.stage;
  const pa = nativeAlliance(st.alliance(player));
  for (const id of camp) {
    if (!living(st.countries.get(id))) continue;
    const ca = nativeAlliance(st.alliance(id));
    if (ca !== 4 && ca !== pa) return true;
  }
  return false;
}

function elimStamp(st) {
  let n = 0;
  for (const c of st.countries.values()) if (c.eliminated) n++;
  return n;
}

let _cache = null;

function getCamps(game) {
  const st = game.stage;
  const player = st.player;
  const rev = game.diplomacy?.revision || 0;
  const elim = elimStamp(st);
  if (_cache && _cache.game === game && _cache.rev === rev && _cache.elim === elim && _cache.player === player) {
    return _cache;
  }

  const livingIds = [];
  for (const c of st.countries.values()) if (c && !c.eliminated) livingIds.push(c.id);

  const byId = new Map();
  const componentOf = id => {
    if (byId.has(id)) return byId.get(id);
    const camp = allianceComponent(game, id);
    for (const m of camp) byId.set(m, camp);
    return camp;
  };
  for (const id of livingIds) componentOf(id);

  const playerCamp = componentOf(player);
  const redCamp = new Set();
  for (const id of livingIds) {
    if (id === player) continue;
    if (getDiplomaticRelation(game, player, id) !== DIPLOMACY_STATE.WAR) continue;
    for (const m of componentOf(id)) redCamp.add(m);
  }

  _cache = { game, rev, elim, player, playerCamp, redCamp, componentOf };
  return _cache;
}

export function relationColor(game, country) {
  return KIND_COLOR[relationKind(game, country)] || 'gray';
}

export function relationLabel(game, country) {
  return KIND_LABEL[relationKind(game, country)] || KIND_LABEL.neutral;
}

export function countryCaptionName(game, country) {
  const info = game?.stage?.countries?.get(country);
  const flag = info?.flag || country;
  return COUNTRY_NAMES[country] || COUNTRY_NAMES[flag] || country || '未知国家';
}

export function relationCaption(game, country) {
  return `${countryCaptionName(game, country)} · ${relationLabel(game, country)}`;
}

export function paintHex(color) {
  return (BASE_COLOR_TABLE[color] && BASE_COLOR_TABLE[color].hex) || '#7a7672';
}

// Semantic relation, independent of paint. Diplomacy UI can still say
// "同盟" / "共同作战"; both paint as ally blue. The player himself is green.
export function relationKind(game, country) {
  const st = game.stage;
  const player = st.player;
  if (!country) return 'neutral';
  if (country === player) return 'player';

  const dip = game.diplomacy;
  if (!dip || !dip.enabled) {
    if (nativeAlliance(st.alliance(country)) === 4) return 'neutral';
    return st.areAllied(player, country) ? 'alliance' : 'war';
  }

  const { playerCamp, redCamp, componentOf } = getCamps(game);
  const camp = componentOf(country);
  if (redCamp.has(country)) return 'war';
  if (playerCamp.has(country)) return 'alliance';
  if (campsShareWar(game, camp, redCamp)) return 'cobelligerent';
  if (campsShareWar(game, camp, playerCamp) || (campHostileNative(game, camp, player) && campIsBelligerent(game, camp))) return 'tense';
  return 'neutral';
}
